--
-- Table structure for table `fact_payment`
--

DROP TABLE IF EXISTS `fact_payment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_payment` (
  `payment_key` bigint NOT NULL,
  `source_id` text,
  `source_system` text,
  `subscription_key` bigint DEFAULT NULL,
  `company_key` bigint DEFAULT NULL,
  `status_key` bigint DEFAULT NULL,
  `paid_date_key` double DEFAULT NULL,
  `amount` double DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`payment_key`),
  KEY `status_key_idx` (`status_key`),
  KEY `company_key_idx` (`company_key`),
  KEY `subscription_key_idx` (`subscription_key`),
  CONSTRAINT `company_key` FOREIGN KEY (`company_key`) REFERENCES `dim_company` (`company_key`),
  CONSTRAINT `status_key` FOREIGN KEY (`status_key`) REFERENCES `dim_status` (`status_key`),
  CONSTRAINT `subscription_key` FOREIGN KEY (`subscription_key`) REFERENCES `fact_subscription` (`subscription_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
