CREATE TABLE `fact_subscription` (
  `subscription_key` bigint NOT NULL,
  `source_id` text,
  `source_system` text,
  `company_key` bigint DEFAULT NULL,
  `plan_key` bigint DEFAULT NULL,
  `module_key` bigint DEFAULT NULL,
  `status_key` bigint DEFAULT NULL,
  `start_date_key` bigint DEFAULT NULL,
  `end_date_key` bigint DEFAULT NULL,
  `duration_days` bigint DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `duration_gap_days` bigint DEFAULT NULL,
  `duration_outlier_flag` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`subscription_key`),
  KEY `company_key_idx` (`company_key`),
  KEY `plan_key_idx` (`plan_key`),
  KEY `module_key_idx` (`module_key`),
  KEY `status_key_idx` (`status_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
